const http = require('http'); const fs = require('fs'); const path = require('path');
const root = path.join(__dirname, '..', 'public');
const types = { '.html':'text/html; charset=utf-8', '.js':'application/javascript', '.css':'text/css', '.png':'image/png', '.jpg':'image/jpeg' };
http.createServer((req,res)=>{
  let p = decodeURIComponent(req.url.split('?')[0]);
  if(p==='/') p='/__probe_select.html';
  const f = path.join(root, p);
  fs.readFile(f,(e,d)=>{ if(e){res.writeHead(404);res.end('nf '+p);return;} res.writeHead(200,{'Content-Type':types[path.extname(f)]||'application/octet-stream'}); res.end(d); });
}).listen(8097, ()=>console.log('static on 8097'));

