  this.busCodeTypedKeyword = (query || '').trim()
  if (this.busCodeRemoteTimer) {
    clearTimeout(this.busCodeRemoteTimer)
    this.busCodeRemoteTimer = null
  }
  const q = (query || '').trim()
  if (!q) {
    this.fetchBusCodeMenu()
    return
  }
  this.busCodeRemoteTimer = setTimeout(() => {
    this.busCodeRemoteTimer = null
    this.fetchBusCodeMenu(q)
  }, 300)
},
handleBusCodeChange(val) {
  this.busCodeTypedKeyword = ''
  if (val === undefined || val === null || val === '') {
    this.busCodeStickyOption = null
    return
  }
  const hit = this.busCodeOptions.find((o) => String(o.dictValue) === String(val))
  this.busCodeStickyOption = hit ? { ...hit } : null
},
// 点击查询：若用户只输入了业务类型名称但未从下拉中选中，则按名称解析为 busCode，
// 避免“输入内容后点查询就清空、仍无数据”的问题（后端仅支持按 busCode 精确过滤）。
handleQuery() {
  const empty = (v) => v === undefined || v === null || v === ''
  const kw = (this.busCodeTypedKeyword || '').trim()
  if (empty(this.queryParams.busCode) && kw) {
    this.resolveBusCodeByKeyword(kw).then((hit) => {
      if (hit) {
        this.queryParams.busCode = hit.dictValue
        this.busCodeStickyOption = { ...hit }
        if (!this.busCodeOptions.some((o) => String(o.dictValue) === String(hit.dictValue))) {
          this.busCodeOptions = [hit, ...this.busCodeOptions]
        }
      }
      this.queryParams.pageNum = 1
      this.getList()
    })
    return
  }
  this.queryParams.pageNum = 1
  this.getList()
},
// 根据输入的业务类型名称解析出唯一匹配的选项：优先精确匹配，其次唯一模糊匹配
resolveBusCodeByKeyword(kw) {
  const local = this.busCodeOptions || []
  const pick = (list) => {
    const exact = list.find((o) => String(o.dictLabel) === kw)
    if (exact) return exact
    const fuzzy = list.filter((o) => String(o.dictLabel).includes(kw))
    return fuzzy.length === 1 ? fuzzy[0] : null
  }
  const localHit = pick(local)
  if (localHit) return Promise.resolve(localHit)
  return this.$get('/system/menu/listBusCodeMenuByKeyWord', { keyWord: kw })
    .then((res) => {
      const list = (res.data || []).map((e) => ({
        ...e,
        dictLabel: e.menuName,
        dictValue: e.busCode
      }))
      return pick(list)
    })
    .catch(() => null)
},

